/**
 * Curated descriptions of cBioPortal page tabs, used in tool responses
 * to give the LLM accurate context about what each tab shows.
 *
 * These are sourced from the cBioPortal frontend and documentation —
 * NOT generated by the LLM. The LLM is instructed to use this field
 * verbatim and not to supplement it with training-data knowledge.
 *
 * Context params allow tools to produce specific descriptions (e.g. axis
 * labels for plots, group names for comparisons) without LLM involvement.
 * Functions fall back to the static string when context is absent.
 */

type PlotsAxisInput = {
    selectedGeneOption?: string;
    dataType?: string;
    selectedDataSourceOption?: string;
};

export type PlotsDescriptionContext = {
    plotsHorz?: PlotsAxisInput;
    plotsVert?: PlotsAxisInput;
};

export type ResultsViewDescriptionContext = PlotsDescriptionContext & {
    comparisonSelectedGroups?: string[];
};

export type GroupComparisonDescriptionContext = {
    groups?: Array<{ name: string; sampleCount?: number }>;
    attributeName?: string;
};

const DATA_TYPE_LABELS: Record<string, string> = {
    MRNA_EXPRESSION: 'mRNA expression',
    MUTATION_EXTENDED: 'mutation',
    COPY_NUMBER_ALTERATION: 'CNA',
    METHYLATION: 'methylation',
    PROTEIN_LEVEL: 'protein expression',
    STRUCTURAL_VARIANT: 'structural variants',
};

function plotsAxisLabel(sel: PlotsAxisInput): string {
    const {
        selectedGeneOption: gene,
        dataType,
        selectedDataSourceOption: source,
    } = sel;
    if (dataType === 'clinical_attribute') {
        return source?.replace(/_/g, ' ').toLowerCase() ?? 'clinical attribute';
    }
    const typeLabel = dataType
        ? (DATA_TYPE_LABELS[dataType] ?? dataType.toLowerCase())
        : 'data';
    return gene ? `${gene} ${typeLabel}` : typeLabel;
}

function buildGroupStr(context: GroupComparisonDescriptionContext): string {
    if (context.attributeName) {
        return `${context.attributeName} groups`;
    }
    if (context.groups?.length) {
        return context.groups
            .map((g) =>
                g.sampleCount !== undefined
                    ? `${g.name} (${g.sampleCount})`
                    : g.name
            )
            .join(' vs ');
    }
    return '';
}

