export function getPatientViewPageDescription(
    tab: string | undefined
): string | undefined {
    if (!tab) return undefined;
    return PATIENT_VIEW_DESCRIPTIONS[tab];
}

export function getStudyViewPageDescription(
    tab: string | undefined,
    context?: PlotsDescriptionContext
): string | undefined {
    if (!tab) return undefined;
    if (tab === 'plots' && context?.plotsHorz && context?.plotsVert) {
        const vert = plotsAxisLabel(context.plotsVert);
        const horz = plotsAxisLabel(context.plotsHorz);
        return `Scatter/box plots: ${vert} (y-axis) by ${horz} (x-axis).`;
    }
    return STUDY_VIEW_DESCRIPTIONS[tab];
}

export function getResultsViewPageDescription(
    tab: string | undefined,
    context?: ResultsViewDescriptionContext
): string | undefined {
    if (!tab) return undefined;
    if (tab === 'plots' && context?.plotsHorz && context?.plotsVert) {
        const vert = plotsAxisLabel(context.plotsVert);
        const horz = plotsAxisLabel(context.plotsHorz);
        return `Scatter/box plots: ${vert} (y-axis) by ${horz} (x-axis).`;
    }
    if (
        tab.startsWith('comparison/') &&
        context?.comparisonSelectedGroups?.length
    ) {
        const groupStr = context.comparisonSelectedGroups
            .map((g) => `${g}-altered`)
            .join(' vs ');
        const COMPARISON_DYNAMIC: Record<string, string> = {
            'comparison/overlap': `Diagram showing sample and patient overlap across ${groupStr}.`,
            'comparison/survival': `Kaplan-Meier survival comparing ${groupStr}.`,
            'comparison/clinical': `Clinical attribute distributions compared across ${groupStr}.`,
            'comparison/mrna': `mRNA expression for all genes compared across ${groupStr}.`,
            'comparison/protein': `Protein expression for all genes compared across ${groupStr}.`,
            'comparison/dna_methylation': `DNA methylation levels compared across ${groupStr}.`,
            'comparison/alterations': `Genomic alteration rates compared across ${groupStr}.`,
        };
        return COMPARISON_DYNAMIC[tab] ?? RESULTS_VIEW_DESCRIPTIONS[tab];
    }
    return RESULTS_VIEW_DESCRIPTIONS[tab];
}

export function getGroupComparisonPageDescription(
    tab: string | undefined,
    context?: GroupComparisonDescriptionContext
): string | undefined {
    if (!tab) return undefined;
    if (tab.startsWith('generic_assay_')) {
        const type = tab.slice('generic_assay_'.length);
        return (
            GENERIC_ASSAY_TYPE_DESCRIPTIONS[type] ?? GENERIC_ASSAY_DESCRIPTION
        );
    }
    const base = GROUP_COMPARISON_DESCRIPTIONS[tab];
    if (!base || !context) return base;
    const groupStr = buildGroupStr(context);
    if (!groupStr) return base;
    const DYNAMIC: Record<string, string> = {
        overlap: `Diagram showing sample and patient overlap across ${groupStr}.`,
        survival: `Kaplan-Meier survival analysis comparing ${groupStr}.`,
        clinical: `Clinical attribute distributions compared across ${groupStr}.`,
        alterations: `Comparison of genomic alteration rates across ${groupStr}.`,
        mutations: `Mutation frequency (protein change) compared across ${groupStr}.`,
        mrna: `mRNA expression for all genes compared across ${groupStr}.`,
        protein: `Protein expression for all genes compared across ${groupStr}.`,
        dna_methylation: `DNA methylation levels compared across ${groupStr}.`,
    };
    return DYNAMIC[tab] ?? base;
}
